"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { emptyRequestIntake, provisionKeys, type ProvisionKey, type RequestIntake } from "@/lib/commercial/request-intake";
import type { RequestWorkflowMeta, RequestWorkspaceOptions, WorkspaceSpecialty } from "@/lib/commercial/request-workflow";
import { getDemoRequest, saveDemoRequest, type DemoRequestPayload } from "@/lib/commercial/demo-workspace-client";

type ExistingRequest = {
  id:string; clientId:string|null; title:string; source:string; location:string; regionId:string|null; startDate:string|null; durationText:string|null;
  schedule:Record<string,unknown>; lunchPaid:boolean|null; vatMode:string|null; comments:string|null; ownerUserId:string|null;
  roles:Array<{id:string;specialtyId:string;specialty:string;count:number;schedule:Record<string,unknown>;requirements:Record<string,unknown>;targetClientRate:number|string|null}>;
};
type RoleDraft = { id?:string; specialtyId:string; specialtyName:string; count:number; scheduleOverride:boolean; schedule:Record<string,unknown>; requirements:Record<string,unknown>; targetClientRate:number|null };
type ImportPreview = { row:number; specialtyName:string; specialtyId:string; count:number; schedule:Record<string,unknown>; requirements:Record<string,unknown>; targetClientRate:number|null; errors:string[] };
type Props = { options:RequestWorkspaceOptions; intake?:RequestIntake; request?:ExistingRequest; workflowMeta?:RequestWorkflowMeta; demo?:boolean; demoRequestId?:string };
type SimpleProvider = "client"|"us"|"not_required"|"unknown";

const sectionLabels = [
  ["general","Заказчик и объект"],["need","Потребность"],["schedule","График"],["provision","Обеспечение и логистика"],["compliance","Требования к работникам"],["commercial","Коммерческие ориентиры"],
] as const;
const scheduleOptions = [["5/2","5/2"],["6/1","6/1"],["7/0","7/0"],["2/2","2/2"],["3/3","3/3"],["rotation","Вахта"],["on_demand","По заявке"],["custom","Другой"]] as const;
const provisionLabels: Partial<Record<ProvisionKey,string>> = { housing:"Проживание",travel:"Билеты / проезд до региона",shuttle:"Развозка до объекта",meals:"Питание",workwear:"Спецодежда",ppe:"СИЗ",tools:"Инструмент",consumables:"Расходняк" };
const provisionRows = provisionKeys.filter((key)=>provisionLabels[key]);
const providerChoices = [["client","Заказчик"],["us","Мы"],["not_required","Не требуется"]] as const;
const workerCategories = [["rf","РФ"],["eaeu","ЕАЭС"],["foreign_with_docs","Иностранные граждане с разрешительными документами"],["client_rules","По отдельным требованиям заказчика"]] as const;
const checks = [["security","Служба безопасности"],["document_check","Проверка документов"],["qualification","Проверка квалификации"],["medical","Медосмотр"],["medbook","Медицинская книжка"],["labor_safety","Охрана труда"],["industrial_safety","Промышленная безопасность"],["certificates","Удостоверения / допуски"],["pass_docs","Документы для проходной"]] as const;
const accessChoices = [["easy","Удобно"],["public_walk","Транспорт + пешком"],["difficult","Сложный маршрут"],["car_only","Только авто"],["shuttle","Нужна развозка"],["unknown","Уточнить"]] as const;

function object(value:unknown):Record<string,unknown>{return value&&typeof value==="object"&&!Array.isArray(value)?value as Record<string,unknown>:{};}
function text(value:unknown){return typeof value==="string"?value:"";}
function num(value:unknown):number|null{return typeof value==="number"&&Number.isFinite(value)?value:typeof value==="string"&&value.trim()&&Number.isFinite(Number(value))?Number(value):null;}
function patch<T extends object>(current:T,next:Partial<T>):T{return {...current,...next};}
function formatRub(value:number|null){return value===null?"—":`${new Intl.NumberFormat("ru-RU",{maximumFractionDigits:0}).format(value)} ₽`;}
function normalizeProvider(value:string):SimpleProvider{return value==="client"?"client":value==="not_required"?"not_required":value==="unknown"?"unknown":"us";}
function providerText(value:string){const provider=normalizeProvider(value);return provider==="client"?"Заказчик":provider==="us"?"Мы":provider==="not_required"?"Не требуется":"Не указано";}
function legacyRule(intake:RequestIntake,key:ProvisionKey){return providerText(intake.provision[key].provider);}
function normalizeLegacyIntake(value:RequestIntake):RequestIntake{
  const provision={...value.provision};
  for(const key of provisionKeys)provision[key]={...provision[key],provider:normalizeProvider(provision[key].provider)};
  return {...value,provision,logistics:{...value.logistics,brigadierProvider:normalizeProvider(value.logistics.brigadierProvider)}};
}
function inferRegion(address:string, options:RequestWorkspaceOptions["regions"]){
  const value=address.toLowerCase();
  const exact=options.find((region)=>value.includes(region.name.toLowerCase()));
  if(exact)return exact.id;
  if(/(^|[,\s])москва([,\s]|$)/i.test(address))return options.find((region)=>region.name.toLowerCase()==="москва")?.id??"";
  if(/московск(ая|ой)\s+обл/i.test(address))return options.find((region)=>region.name.toLowerCase().includes("москов")&&region.name.toLowerCase().includes("област"))?.id??"";
  return "";
}
function inferCity(address:string){
  if(/(^|[,\s])москва([,\s]|$)/i.test(address))return "Москва";
  const match=address.match(/(?:г\.?|город)\s*([^,]+)/i);
  return match?.[1]?.trim()??"";
}
function emptyRole():RoleDraft{return {specialtyId:"",specialtyName:"",count:1,scheduleOverride:false,schedule:{},requirements:{experienceMode:"not_required",experienceMin:""},targetClientRate:null};}

export function RequestIntakeWorkspacePolished({options,intake:initialIntake,request,workflowMeta,demo=false,demoRequestId}:Props){
  const router=useRouter();
  const fileRef=useRef<HTMLInputElement>(null);
  const [active,setActive]=useState<(typeof sectionLabels)[number][0]>("general");
  const [intake,setIntake]=useState<RequestIntake>(()=>normalizeLegacyIntake(initialIntake??emptyRequestIntake()));
  const [title,setTitle]=useState(request?.title??"");
  const [clientId,setClientId]=useState(request?.clientId??"");
  const [source,setSource]=useState(request?.source==="manual"?"":request?.source??"");
  const [location,setLocation]=useState(request?.location??"");
  const [regionId,setRegionId]=useState(request?.regionId??"");
  const [startDate,setStartDate]=useState(request?.startDate??"");
  const [durationText,setDurationText]=useState(request?.durationText??"");
  const [vatMode,setVatMode]=useState(request?.vatMode??"with_vat");
  const [comments,setComments]=useState(request?.comments??"");
  const [ownerUserId,setOwnerUserId]=useState(request?.ownerUserId??options.currentUserId);
  const [observerUserIds,setObserverUserIds]=useState<string[]>(workflowMeta?.observers.map((item)=>item.id)??[]);
  const [roles,setRoles]=useState<RoleDraft[]>(request?.roles.map((role)=>({id:role.id,specialtyId:role.specialtyId,specialtyName:role.specialty,count:role.count,scheduleOverride:Object.keys(role.schedule??{}).length>0,schedule:role.schedule??{},requirements:role.requirements??{},targetClientRate:num(role.targetClientRate)}))??[emptyRole()]);
  const [expandedRole,setExpandedRole]=useState(0);
  const [advancedVolume,setAdvancedVolume]=useState(Boolean(initialIntake?.volume.guaranteedHours||initialIntake?.volume.guaranteedShifts||initialIntake?.volume.startHeadcount));
  const [importPreview,setImportPreview]=useState<ImportPreview[]>([]);
  const [importOpen,setImportOpen]=useState(false);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState("");

  useEffect(() => {
    if (!demo || !demoRequestId) return;
    const record = getDemoRequest(demoRequestId);
    if (!record) return;
    const draft = record.payload;
    const timer = window.setTimeout(() => {
      setTitle(draft.title); setClientId(draft.clientId ?? ""); setSource(draft.source === "manual" ? "" : draft.source);
      setLocation(draft.location); setRegionId(draft.regionId ?? ""); setStartDate(draft.startDate ?? ""); setDurationText(draft.durationText ?? "");
      setVatMode(draft.vatMode ?? "with_vat"); setComments(draft.comments ?? ""); setOwnerUserId(draft.ownerUserId ?? options.currentUserId); setObserverUserIds(draft.observerUserIds ?? []);
      setIntake(normalizeLegacyIntake(draft.intake as RequestIntake));
      setRoles(draft.roles.map((role) => ({ id:role.id, specialtyId:role.specialtyId ?? "", specialtyName:role.specialtyName, count:role.count, scheduleOverride:Object.keys(role.schedule ?? {}).length > 0, schedule:role.schedule ?? {}, requirements:role.requirements ?? {}, targetClientRate:role.targetClientRate })));
    }, 0);
    return () => window.clearTimeout(timer);
  }, [demo, demoRequestId, options.currentUserId]);

  const totalHeadcount=useMemo(()=>roles.reduce((sum,role)=>sum+(Number.isFinite(role.count)?role.count:0),0),[roles]);
  const region=options.regions.find((item)=>item.id===regionId);
  const yandexMap=location.trim()?`https://yandex.ru/maps/?text=${encodeURIComponent(location.trim())}`:"";

  function updateIntake<K extends keyof RequestIntake>(key:K,value:RequestIntake[K]){setIntake((current)=>({...current,[key]:value}));}
  function rolePatch(index:number,next:Partial<RoleDraft>){setRoles((current)=>current.map((role,roleIndex)=>roleIndex===index?{...role,...next}:role));}
  function requirementPatch(index:number,key:string,value:unknown){setRoles((current)=>current.map((role,roleIndex)=>roleIndex===index?{...role,requirements:{...role.requirements,[key]:value}}:role));}
  function schedulePatch(key:string,value:unknown){updateIntake("schedule",patch(intake.schedule,{[key]:value}));}
  function selectSpecialty(index:number,name:string){const found=options.specialties.find((item)=>item.name.toLowerCase()===name.trim().toLowerCase());rolePatch(index,{specialtyName:name,specialtyId:found?.id??""});}
  function specialtyStats(role:RoleDraft):WorkspaceSpecialty|undefined{return options.specialties.find((item)=>item.id===role.specialtyId)||options.specialties.find((item)=>item.name.toLowerCase()===role.specialtyName.trim().toLowerCase());}
  function onAddress(value:string){setLocation(value);const autoRegion=inferRegion(value,options.regions);if(autoRegion)setRegionId(autoRegion);const autoCity=inferCity(value);if(autoCity)updateIntake("object",patch(intake.object,{city:autoCity}));}
  function addMessenger(){updateIntake("contact",patch(intake.contact,{messengers:[...intake.contact.messengers,{type:"Telegram",value:""}]}));}
  function updateMessenger(index:number,key:"type"|"value",value:string){updateIntake("contact",patch(intake.contact,{messengers:intake.contact.messengers.map((item,itemIndex)=>itemIndex===index?{...item,[key]:value}:item)}));}
  function removeMessenger(index:number){updateIntake("contact",patch(intake.contact,{messengers:intake.contact.messengers.filter((_,itemIndex)=>itemIndex!==index)}));}
  function setProvisionProvider(key:ProvisionKey,provider:SimpleProvider){updateIntake("provision",{...intake.provision,[key]:{...intake.provision[key],provider,cost:null,unit:""}});}

  async function save(){
    setBusy(true);setError("");
    try{
      const resolvedPattern=intake.schedule.pattern==="custom"?intake.schedule.customPattern:intake.schedule.pattern;
      const payload={
        clientId:clientId||null,title:title.trim(),source:source.trim()||"manual",location:location.trim(),regionId:regionId||null,startDate:startDate||null,durationText:durationText||null,
        schedule:{pattern:resolvedPattern,shiftStart:intake.schedule.shiftStart,shiftEnd:intake.schedule.shiftEnd,presenceHours:intake.schedule.presenceHours,paidHours:intake.schedule.paidHours,lunchMinutes:intake.schedule.lunchMinutes,shiftType:intake.schedule.shiftType,rotationDays:intake.schedule.rotationDays},
        intake,lunchPaid:intake.schedule.lunchPaid,vatMode,comments:comments||null,ownerUserId:ownerUserId||options.currentUserId,observerUserIds,
        roles:roles.filter((role)=>role.specialtyName.trim()).map((role)=>({id:role.id,specialtyId:role.specialtyId||null,specialtyName:role.specialtyName.trim(),count:Math.max(1,role.count),schedule:role.scheduleOverride?role.schedule:{},requirements:role.requirements,targetClientRate:role.targetClientRate})),
        housingRule:legacyRule(intake,"housing"),travelRule:legacyRule(intake,"travel"),shuttleRule:legacyRule(intake,"shuttle"),ppeRule:`${legacyRule(intake,"workwear")} / ${legacyRule(intake,"ppe")}`,medicalRule:`${legacyRule(intake,"medical")} / ${legacyRule(intake,"medbook")}`,citizenshipRule:intake.compliance.workerCategories.join(", "),toolsRule:legacyRule(intake,"tools"),
      };
      if(!payload.title||payload.title.length<3)throw new Error("Укажите название заявки");
      if (demo) {
        const clientName = options.clients.find((item) => item.id === payload.clientId)?.name;
        const ownerName = options.members.find((item) => item.id === payload.ownerUserId)?.name;
        const saved = saveDemoRequest(payload as DemoRequestPayload, { id:demoRequestId ?? request?.id, clientName, ownerName, actorId:options.currentUserId });
        router.push(`/requests?demo=${encodeURIComponent(saved.id)}`); router.refresh(); return;
      }
      const response=await fetch(request?`/api/requests/${request.id}/v2`:"/api/requests/v2",{method:request?"PATCH":"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});
      const json=await response.json().catch(()=>({}));if(!response.ok)throw new Error(json.error??"Не удалось сохранить заявку");
      router.push(`/requests/${json.id??request?.id}`);router.refresh();
    }catch(saveError){setError(saveError instanceof Error?saveError.message:"Не удалось сохранить заявку");}finally{setBusy(false);}
  }
  async function archive(){if(!request&&!demoRequestId)return;if(!window.confirm("Переместить заявку в архив? Архив предназначен для дублей, ошибочных и технических записей."))return;setBusy(true);setError("");try{if(demo){const current=getDemoRequest(demoRequestId??request?.id??"");if(current)saveDemoRequest(current.payload,{id:current.id,base:{...current.board,archivedAt:new Date().toISOString()},clientName:current.board.client,ownerName:current.board.owner??undefined,actorId:options.currentUserId});router.push("/requests");router.refresh();return;}if(!request)return;const response=await fetch(`/api/requests/${request.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({action:"archive"})});const json=await response.json().catch(()=>({}));if(!response.ok)throw new Error(json.error??"Не удалось архивировать");router.push("/requests");router.refresh();}catch(archiveError){setError(archiveError instanceof Error?archiveError.message:"Не удалось архивировать");}finally{setBusy(false);}}
  async function importFile(file:File){setError("");try{const rows=await readSpreadsheet(file);const preview=rowsToPreview(rows,options.specialties);setImportPreview(preview);setImportOpen(true);}catch(importError){setError(importError instanceof Error?importError.message:"Не удалось прочитать файл");}}
  function applyImport(){const valid=importPreview.filter((row)=>row.errors.length===0);if(!valid.length)return;setRoles((current)=>[...current.filter((role)=>role.specialtyName.trim()),...valid.map((row)=>({specialtyId:row.specialtyId,specialtyName:row.specialtyName,count:row.count,scheduleOverride:Object.keys(row.schedule).length>0,schedule:row.schedule,requirements:row.requirements,targetClientRate:row.targetClientRate}))]);setImportOpen(false);setImportPreview([]);}
  function downloadTemplate(){const xml=excelTemplate();const blob=new Blob([xml],{type:"application/vnd.ms-excel;charset=utf-8"});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download="Шаблон_позиций_заявки.xls";link.click();URL.revokeObjectURL(url);}

  return <div className="request-v2-layout">
    <aside className="request-v2-nav"><div className="request-v2-nav-summary"><strong>{request?"Редактирование заявки":"Новая заявка"}</strong><span>{totalHeadcount} чел. · {roles.filter((role)=>role.specialtyName.trim()).length} позиций</span></div>{sectionLabels.map(([code,label],index)=><button type="button" key={code} className={active===code?"active":""} onClick={()=>setActive(code)}><span>{index+1}</span>{label}</button>)}</aside>
    <main className="request-v2-main">
      {error&&<div className="request-warning"><strong>Проверьте данные.</strong> {error}</div>}

      {active==="general"&&<section className="request-v2-section"><header><div><span>01</span><h2>Заказчик и объект</h2><p>Основная информация, которую менеджер фиксирует во время разговора с заказчиком.</p></div></header>
        <div className="request-form-grid cols-2"><label>Название заявки<input value={title} onChange={(event)=>setTitle(event.target.value)} placeholder="Например, персонал на склад Руднево"/></label><label>Клиент в базе<select value={clientId} onChange={(event)=>setClientId(event.target.value)}><option value="">Пока не привязан</option>{options.clients.map((item)=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div>
        <div className="request-form-grid cols-2"><label>Компания / рабочее название<input value={intake.companyName} onChange={(event)=>updateIntake("companyName",event.target.value)} placeholder="ООО «Компания»"/></label><label>Источник заявки<input list="request-source-options" value={source} onChange={(event)=>setSource(event.target.value)} placeholder="Телефон, мессенджер, тендер…"/><datalist id="request-source-options"><option value="Входящий звонок"/><option value="Эл. почта"/><option value="Telegram"/><option value="WhatsApp"/><option value="Сайт"/><option value="Тендер"/><option value="Повторное обращение"/><option value="Рекомендация"/><option value="Холодный контакт"/></datalist></label></div>
        <div className="request-address-card"><div className="request-address-main"><label>Адрес объекта<input value={location} onChange={(event)=>onAddress(event.target.value)} placeholder="Город, улица, дом или название площадки"/></label>{yandexMap&&<a className="button" target="_blank" rel="noreferrer" href={yandexMap}>Открыть на Яндекс Картах</a>}</div><div className="request-address-meta"><span>{intake.object.city||"Город определится по адресу"}</span><i/><span>{region?.name||"Регион определится автоматически"}</span></div><div className="request-object-row"><label>Объект / площадка<input value={intake.object.siteName} onChange={(event)=>updateIntake("object",patch(intake.object,{siteName:event.target.value}))} placeholder="Например, склад №2"/></label><label>Тип объекта<select value={intake.object.objectType} onChange={(event)=>updateIntake("object",patch(intake.object,{objectType:event.target.value}))}><option value="">Не указан</option><option>Склад</option><option>Производство</option><option>Строительство</option><option>Офис</option><option>Другое</option></select></label></div></div>
        <div className="request-subsection"><h3>Транспортная доступность</h3><div className="request-access-choices">{accessChoices.map(([value,label])=><button type="button" key={value} className={`request-access-choice${intake.object.accessType===value?" active":""}`} onClick={()=>updateIntake("object",patch(intake.object,{accessType:value}))}>{label}</button>)}</div><label>Комментарий по доступности<input value={intake.object.accessComment} onChange={(event)=>updateIntake("object",patch(intake.object,{accessComment:event.target.value}))} placeholder="Например: автобус 15 минут, остановка в 300 м"/></label></div>
        <div className="request-subsection"><h3>Контактное лицо</h3><div className="request-form-grid cols-3"><label>Имя / ФИО<input value={intake.contact.name} onChange={(event)=>updateIntake("contact",patch(intake.contact,{name:event.target.value}))}/></label><label>Телефон<input type="tel" value={intake.contact.phone} onChange={(event)=>updateIntake("contact",patch(intake.contact,{phone:event.target.value}))}/></label><label>Эл. почта<input type="email" value={intake.contact.email} onChange={(event)=>updateIntake("contact",patch(intake.contact,{email:event.target.value}))}/></label></div><div className="messenger-list">{intake.contact.messengers.map((item,index)=><div className="messenger-row" key={`${index}-${item.type}`}><select value={item.type} onChange={(event)=>updateMessenger(index,"type",event.target.value)}><option>Telegram</option><option>WhatsApp</option><option>MAX</option><option>Другое</option></select><input value={item.value} onChange={(event)=>updateMessenger(index,"value",event.target.value)} placeholder="Ник или номер"/><button className="request-icon-button" type="button" onClick={()=>removeMessenger(index)}>×</button></div>)}<button className="request-subtle-action" type="button" onClick={addMessenger}>+ Добавить мессенджер</button></div></div>
        <details className="request-advanced"><summary>Дополнительные реквизиты объекта</summary><div className="request-form-grid cols-3"><label>Город вручную<input value={intake.object.city} onChange={(event)=>updateIntake("object",patch(intake.object,{city:event.target.value}))}/></label><label>Регион вручную<select value={regionId} onChange={(event)=>setRegionId(event.target.value)}><option value="">Не указан</option>{options.regions.map((item)=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>Ориентир<input value={intake.object.landmark} onChange={(event)=>updateIntake("object",patch(intake.object,{landmark:event.target.value}))}/></label></div></details>
      </section>}

      {active==="need"&&<section className="request-v2-section"><header><div><span>02</span><h2>Потребность</h2><p>Общая численность формируется автоматически из позиций.</p></div><div className="request-headcount"><strong>{totalHeadcount}</strong><span>человек всего</span></div></header>
        <div className="request-form-grid cols-3"><label>Плановый старт<input type="date" value={startDate} onChange={(event)=>setStartDate(event.target.value)}/></label><label>Срок работы<select value={durationText} onChange={(event)=>setDurationText(event.target.value)}><option value="">Уточняется</option><option>До 1 месяца</option><option>1–3 месяца</option><option>3–6 месяцев</option><option>6–12 месяцев</option><option>Более 12 месяцев</option><option>Бессрочно</option></select></label><label>Тип потребности<select value={intake.volume.demandType} onChange={(event)=>updateIntake("volume",patch(intake.volume,{demandType:event.target.value}))}><option value="fixed">Постоянная численность</option><option value="variable">Численность может меняться</option><option value="on_demand">По заявкам заказчика</option><option value="one_time">Разовый объём</option><option value="unknown">Пока неизвестно</option></select></label></div>
        <div className="request-roles-head"><div><h3>Позиции</h3><p>Общий график применяется автоматически; исключения задаются внутри конкретной позиции.</p></div><div><button type="button" className="button" onClick={downloadTemplate}>Скачать шаблон таблицы</button><button type="button" className="button" onClick={()=>fileRef.current?.click()}>Загрузить таблицу</button><input ref={fileRef} hidden type="file" accept=".xlsx,.xls,.csv,.tsv" onChange={(event)=>{const file=event.target.files?.[0];if(file)void importFile(file);event.currentTarget.value="";}}/><button type="button" className="button primary" onClick={()=>{setRoles((current)=>[...current,emptyRole()]);setExpandedRole(roles.length);}}>+ Добавить позицию</button></div></div>
        <div className="role-accordion">{roles.map((role,index)=><RoleAccordion key={role.id??`new-${index}`} role={role} index={index} expanded={expandedRole===index} options={options} stats={specialtyStats(role)} onToggle={()=>setExpandedRole(expandedRole===index?-1:index)} onRole={rolePatch} onRequirement={requirementPatch} onSpecialty={selectSpecialty} onRemove={()=>setRoles((current)=>current.filter((_,roleIndex)=>roleIndex!==index))}/>)}</div>
        <details className="request-advanced" open={advancedVolume} onToggle={(event)=>setAdvancedVolume(event.currentTarget.open)}><summary>Дополнительные условия объёма и запуска</summary><div className="request-form-grid cols-3"><label>Первый вывод, чел.<input type="number" min="1" value={intake.volume.startHeadcount??""} onChange={(event)=>updateIntake("volume",patch(intake.volume,{startHeadcount:num(event.target.value)}))}/></label><label>Гарантированные часы / месяц<input type="number" min="0" value={intake.volume.guaranteedHours??""} onChange={(event)=>updateIntake("volume",patch(intake.volume,{guaranteedHours:num(event.target.value)}))}/></label><label>Гарантированные смены<input type="number" min="0" value={intake.volume.guaranteedShifts??""} onChange={(event)=>updateIntake("volume",patch(intake.volume,{guaranteedShifts:num(event.target.value)}))}/></label></div><label>Комментарий к объёму<textarea value={intake.volume.comment} onChange={(event)=>updateIntake("volume",patch(intake.volume,{comment:event.target.value}))} placeholder="Например: первые две недели 10 человек, затем выход на полную численность"/></label></details>
      </section>}

      {active==="schedule"&&<section className="request-v2-section"><header><div><span>03</span><h2>Общий график</h2><p>Базовые условия для всех позиций. Различия указываются внутри конкретной позиции.</p></div></header><div className="request-form-grid cols-4"><label>График<select value={intake.schedule.pattern} onChange={(event)=>schedulePatch("pattern",event.target.value)}><option value="">Уточняется</option>{scheduleOptions.map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label>{intake.schedule.pattern==="custom"&&<label>Свой график<input value={intake.schedule.customPattern} onChange={(event)=>schedulePatch("customPattern",event.target.value)}/></label>}<label>Начало<input type="time" value={intake.schedule.shiftStart} onChange={(event)=>schedulePatch("shiftStart",event.target.value)}/></label><label>Конец<input type="time" value={intake.schedule.shiftEnd} onChange={(event)=>schedulePatch("shiftEnd",event.target.value)}/></label><label>Тип смены<select value={intake.schedule.shiftType} onChange={(event)=>schedulePatch("shiftType",event.target.value)}><option value="day">Дневная</option><option value="night">Ночная</option><option value="mixed">День / ночь</option></select></label></div><div className="request-form-grid cols-4"><label>Часов присутствия<input type="number" min="1" step="0.5" value={intake.schedule.presenceHours??""} onChange={(event)=>schedulePatch("presenceHours",num(event.target.value))}/></label><label>Оплачиваемых часов<input type="number" min="1" step="0.5" value={intake.schedule.paidHours??""} onChange={(event)=>schedulePatch("paidHours",num(event.target.value))}/></label><label>Обед, минут<input type="number" min="0" value={intake.schedule.lunchMinutes??""} onChange={(event)=>schedulePatch("lunchMinutes",num(event.target.value))}/></label><label className="request-checkbox-card"><input type="checkbox" checked={intake.schedule.lunchPaid} onChange={(event)=>schedulePatch("lunchPaid",event.target.checked)}/><span><strong>Обед оплачивается</strong><small>Иначе оплачиваемые часы считаются без обеда</small></span></label></div>{intake.schedule.pattern==="rotation"&&<div className="request-form-grid cols-2"><label>Продолжительность вахты, дней<input type="number" min="1" value={intake.schedule.rotationDays??""} onChange={(event)=>schedulePatch("rotationDays",num(event.target.value))}/></label></div>}<label>Особенности графика<textarea value={intake.schedule.overtimeNotes} onChange={(event)=>schedulePatch("overtimeNotes",event.target.value)} placeholder="Переработки, праздники, плавающий старт и другие особенности — только если они есть"/></label></section>}

      {active==="provision"&&<section className="request-v2-section"><header><div><span>04</span><h2>Обеспечение и логистика</h2><p>Отмечаем, что предоставляет заказчик, а что включаем в нашу организацию. Стоимость определяется уже в расчёте.</p></div></header><div className="provision-matrix provision-matrix-polished"><div className="provision-matrix-head"><span>Условие</span><span>Кто обеспечивает</span><span>Комментарий</span></div>{provisionRows.map((key)=>{const selected=normalizeProvider(intake.provision[key].provider);return <div className="provision-matrix-row" key={key}><strong>{provisionLabels[key]}</strong><div className="request-provider-options" role="radiogroup" aria-label={provisionLabels[key]}>{providerChoices.map(([value,label])=><button key={value} type="button" role="radio" aria-checked={selected===value} className={`request-provider-option${selected===value?" active":""}`} onClick={()=>setProvisionProvider(key,value)}>{label}</button>)}</div><input className="request-provision-comment" value={intake.provision[key].comment} onChange={(event)=>updateIntake("provision",{...intake.provision,[key]:{...intake.provision[key],comment:event.target.value}})} placeholder="При необходимости"/></div>})}<div className="provision-matrix-row"><strong>Бригадир</strong><div className="request-provider-options" role="radiogroup" aria-label="Бригадир">{providerChoices.map(([value,label])=>{const selected=normalizeProvider(intake.logistics.brigadierProvider)===value;return <button key={value} type="button" role="radio" aria-checked={selected} className={`request-provider-option${selected?" active":""}`} onClick={()=>updateIntake("logistics",patch(intake.logistics,{brigadierProvider:value}))}>{label}</button>})}</div><span className="request-provider-note">Если условия нестандартные, уточните их в общем комментарии.</span></div></div><div className="request-form-grid cols-2"><label>Кому требуется проживание<select value={intake.logistics.housingScope} onChange={(event)=>updateIntake("logistics",patch(intake.logistics,{housingScope:event.target.value}))}><option value="all">Всем сотрудникам</option><option value="nonlocal">Только иногородним</option><option value="as_needed">По необходимости</option><option value="not_required">Не требуется</option></select></label></div></section>}

      {active==="compliance"&&<section className="request-v2-section"><header><div><span>05</span><h2>Требования к работникам и допуску</h2><p>Документы, проверки и ограничения для допуска к объекту.</p></div></header><div className="request-compliance-grid"><div className="request-compliance-group"><h3>Кто подходит</h3><p>Можно выбрать несколько категорий.</p>{workerCategories.map(([value,label])=><label className="request-check-row" key={value}><input type="checkbox" checked={intake.compliance.workerCategories.includes(value)} onChange={(event)=>updateIntake("compliance",patch(intake.compliance,{workerCategories:event.target.checked?[...intake.compliance.workerCategories,value]:intake.compliance.workerCategories.filter((item)=>item!==value)}))}/><span>{label}</span></label>)}</div><div className="request-compliance-group"><h3>Проверки и документы</h3><p>Отмечаем только то, что действительно требуется для выхода.</p>{checks.map(([value,label])=><label className="request-check-row" key={value}><input type="checkbox" checked={intake.compliance.documentChecks.includes(value)} onChange={(event)=>updateIntake("compliance",patch(intake.compliance,{documentChecks:event.target.checked?[...intake.compliance.documentChecks,value]:intake.compliance.documentChecks.filter((item)=>item!==value)}))}/><span>{label}</span></label>)}</div></div><label>Комментарий по допускам<textarea value={intake.compliance.comment} onChange={(event)=>updateIntake("compliance",patch(intake.compliance,{comment:event.target.value}))} placeholder="Например: удостоверение по работе на высоте, конкретная группа допуска, особенности проверки службы безопасности"/></label></section>}

      {active==="commercial"&&<section className="request-v2-section"><header><div><span>06</span><h2>Коммерческие ориентиры</h2><p>Внутренний блок менеджера. Во внешней форме наши исторические ставки и экономика не показываются.</p></div></header><div className="request-form-grid cols-3"><label>Как платит заказчик<select value={intake.commercial.billingUnit} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{billingUnit:event.target.value}))}><option value="unknown">Пока неизвестно</option><option value="hour">Человеко-час</option><option value="shift">Смена</option><option value="worker_month">Сотрудник / месяц</option><option value="unit">За единицу</option><option value="volume">За объём</option><option value="fixed">Фикс за проект</option><option value="mixed">Смешанная</option></select></label><label>Лимит / ставка заказчика<input type="number" min="0" value={intake.commercial.clientLimit??""} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{clientLimit:num(event.target.value)}))}/></label><label>НДС для лимита<select value={intake.commercial.clientLimitVatMode} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{clientLimitVatMode:event.target.value}))}><option value="with_vat">С НДС</option><option value="without_vat">Без НДС</option></select></label></div><div className="request-form-grid cols-3"><label>Желаемая зарплата сотруднику<input type="number" min="0" value={intake.commercial.desiredWorkerNet??""} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{desiredWorkerNet:num(event.target.value)}))}/></label><label>Единица зарплаты<select value={intake.commercial.desiredWorkerNetUnit} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{desiredWorkerNetUnit:event.target.value}))}><option value="hour">В час</option><option value="shift">За смену</option><option value="month">В месяц</option></select></label><label>НДС нашей ставки<select value={vatMode} onChange={(event)=>setVatMode(event.target.value)}><option value="with_vat">Показывать с НДС</option><option value="without_vat">Без НДС</option></select></label></div><div className="request-form-grid cols-3"><label>Известная ставка конкурента<input type="number" min="0" value={intake.commercial.competitorRate??""} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{competitorRate:num(event.target.value)}))}/></label><label>НДС конкурента<select value={intake.commercial.competitorRateVatMode} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{competitorRateVatMode:event.target.value}))}><option value="with_vat">С НДС</option><option value="without_vat">Без НДС</option></select></label><label>Комментарий<input value={intake.commercial.competitorComment} onChange={(event)=>updateIntake("commercial",patch(intake.commercial,{competitorComment:event.target.value}))}/></label></div><div className="historical-rate-grid">{roles.filter((role)=>role.specialtyName.trim()).map((role,index)=>{const stat=specialtyStats(role);return <article key={`${role.specialtyName}-${index}`}><strong>{role.specialtyName}</strong>{stat&&stat.stats.sampleCount>0?<><span>Заказчику: {formatRub(stat.stats.clientRateMin)}–{formatRub(stat.stats.clientRateMax)} / ч</span><span>Медиана: {formatRub(stat.stats.clientRateMedian)} / ч</span><span>Сотруднику: {formatRub(stat.stats.workerPayMin)}–{formatRub(stat.stats.workerPayMax)}</span><small>По {stat.stats.sampleCount} похожим сохранённым расчётам. Это ориентир, не готовая цена.</small></>:<small>Недостаточно истории для надёжного ориентира.</small>}</article>})}</div><label>Общий комментарий к заявке<textarea value={comments} onChange={(event)=>setComments(event.target.value)} placeholder="Информация, которой нет в структурированных полях"/></label><div className="request-subsection"><h3>Ответственность внутри компании</h3><div className="request-form-grid cols-2"><label>Ответственный<select value={ownerUserId} onChange={(event)=>setOwnerUserId(event.target.value)}>{options.members.map((item)=><option key={item.id} value={item.id}>{item.name}</option>)}</select><small>По умолчанию ответственным становится создатель заявки.</small></label><label>Наблюдатели<select multiple value={observerUserIds} onChange={(event)=>setObserverUserIds(Array.from(event.currentTarget.selectedOptions).map((option)=>option.value))}>{options.members.filter((item)=>item.id!==ownerUserId).map((item)=><option key={item.id} value={item.id}>{item.name}</option>)}</select><small>Наблюдатели видят заявку, но не становятся её ответственными.</small></label></div></div></section>}

      <div className="request-v2-sticky"><div><span>{demo ? "Демо-версия сохранится в браузере и сразу появится в воронке" : request?"Изменения сохранятся в истории заявки":"Черновик можно сохранить даже с неполными данными"}</span>{(request||demoRequestId)&&<button type="button" className="request-danger-link" disabled={busy} onClick={archive}>В архив</button>}</div><div><Link href="/requests" className="button">Отмена</Link><button type="button" className="button primary" disabled={busy} onClick={save}>{busy?"Сохраняю…":(request||demoRequestId)?"Сохранить изменения":"Создать заявку"}</button></div></div>
    </main>

    {importOpen&&<div className="request-modal-backdrop"><div className="request-import-modal"><header><div><strong>Предпросмотр загрузки</strong><span>Найдено строк: {importPreview.length}. С ошибками: {importPreview.filter((row)=>row.errors.length).length}.</span></div><button type="button" className="request-icon-button" onClick={()=>setImportOpen(false)}>×</button></header><div className="request-import-table"><table><thead><tr><th>Строка</th><th>Специальность</th><th>Количество</th><th>График</th><th>Проверка</th></tr></thead><tbody>{importPreview.map((row)=><tr key={row.row} className={row.errors.length?"has-error":""}><td>{row.row}</td><td>{row.specialtyName}{!row.specialtyId&&row.specialtyName&&<small>Новая специальность</small>}</td><td>{row.count||"—"}</td><td>{text(row.schedule.pattern)||"общий"}</td><td>{row.errors.length?<span>{row.errors.join("; ")}</span>:<strong>Готово</strong>}</td></tr>)}</tbody></table></div><footer><button className="button" type="button" onClick={()=>setImportOpen(false)}>Отмена</button><button className="button primary" type="button" disabled={!importPreview.some((row)=>row.errors.length===0)} onClick={applyImport}>Загрузить корректные ({importPreview.filter((row)=>row.errors.length===0).length})</button></footer></div></div>}
  </div>;
}

function RoleAccordion({role,index,expanded,options,stats,onToggle,onRole,onRequirement,onSpecialty,onRemove}:{role:RoleDraft;index:number;expanded:boolean;options:RequestWorkspaceOptions;stats?:WorkspaceSpecialty;onToggle:()=>void;onRole:(index:number,next:Partial<RoleDraft>)=>void;onRequirement:(index:number,key:string,value:unknown)=>void;onSpecialty:(index:number,name:string)=>void;onRemove:()=>void}){
  const expMode=text(role.requirements.experienceMode)||"not_required";
  return <article className={`request-role-card${expanded?" expanded":""}`}><button className="request-role-summary" type="button" onClick={onToggle}><div><strong>{role.specialtyName||`Новая позиция ${index+1}`}</strong><span>{role.count} чел. · {role.scheduleOverride?"свой график":"общий график"} · {expMode==="required"?`опыт ${text(role.requirements.experienceMin)||"обязателен"}`:expMode==="preferred"?"опыт желателен":"опыт не требуется"}</span></div><div>{role.targetClientRate!==null&&<em>{formatRub(role.targetClientRate)} ориентир</em>}<b>{expanded?"−":"+"}</b></div></button>{expanded&&<div className="request-role-body"><div className="request-form-grid cols-3"><label>Специальность<input list={`specialty-${index}`} value={role.specialtyName} onChange={(event)=>onSpecialty(index,event.target.value)} placeholder="Начните вводить название"/><datalist id={`specialty-${index}`}>{options.specialties.map((item)=><option value={item.name} key={item.id}/>)}</datalist><small>{role.specialtyId?"Выбрано из справочника":"Если точного совпадения нет, новая специальность будет создана при сохранении."}</small></label><label>Количество<input type="number" min="1" max="5000" value={role.count} onChange={(event)=>onRole(index,{count:Math.max(1,Number(event.target.value)||1)})}/></label><label>Разряд / квалификация<input value={text(role.requirements.grade)} onChange={(event)=>onRequirement(index,"grade",event.target.value)} placeholder="Если применимо"/></label></div><div className="request-form-grid cols-3"><label>Требование к опыту<select value={expMode} onChange={(event)=>onRequirement(index,"experienceMode",event.target.value)}><option value="not_required">Не требуется</option><option value="preferred">Желателен</option><option value="required">Обязателен</option></select></label>{expMode==="required"&&<label>Минимальный опыт<select value={text(role.requirements.experienceMin)} onChange={(event)=>onRequirement(index,"experienceMin",event.target.value)}><option value="">Уточнить</option><option value="6 месяцев">6 месяцев</option><option value="1 год">1 год</option><option value="2 года">2 года</option><option value="3 года">3 года</option><option value="5+ лет">5+ лет</option></select></label>}<label>Ориентир заказчика, ₽<input type="number" min="0" value={role.targetClientRate??""} onChange={(event)=>onRole(index,{targetClientRate:num(event.target.value)})}/></label></div><div className="request-form-grid cols-2"><label>Что будет делать<textarea value={text(role.requirements.description)} onChange={(event)=>onRequirement(index,"description",event.target.value)} placeholder="Кратко: задачи и зона ответственности"/></label><label>Навыки / требования<textarea value={text(role.requirements.skills)} onChange={(event)=>onRequirement(index,"skills",event.target.value)} placeholder="Что человек должен уметь"/></label></div><div className="request-form-grid cols-2"><label>Удостоверения / допуски<input value={text(role.requirements.certificates)} onChange={(event)=>onRequirement(index,"certificates",event.target.value)} placeholder="НАКС, высота, электробезопасность…"/></label><label>Комментарий по позиции<input value={text(role.requirements.comment)} onChange={(event)=>onRequirement(index,"comment",event.target.value)}/></label></div><label className="request-checkbox-card compact"><input type="checkbox" checked={role.scheduleOverride} onChange={(event)=>onRole(index,{scheduleOverride:event.target.checked,schedule:event.target.checked?role.schedule:{}})}/><span><strong>У позиции свой график</strong><small>Включайте только если он отличается от общего.</small></span></label>{role.scheduleOverride&&<div className="request-form-grid cols-3"><label>График<input value={text(role.schedule.pattern)} onChange={(event)=>onRole(index,{schedule:{...role.schedule,pattern:event.target.value}})}/></label><label>Оплачиваемых часов<input type="number" value={num(role.schedule.paidHours)??""} onChange={(event)=>onRole(index,{schedule:{...role.schedule,paidHours:num(event.target.value)}})}/></label><label>Комментарий<input value={text(role.schedule.comment)} onChange={(event)=>onRole(index,{schedule:{...role.schedule,comment:event.target.value}})}/></label></div>}{stats&&stats.stats.sampleCount>0&&<div className="request-role-rate-hint"><strong>Наша история по этой специальности</strong><span>Ставка заказчику: {formatRub(stats.stats.clientRateMin)}–{formatRub(stats.stats.clientRateMax)} / ч, медиана {formatRub(stats.stats.clientRateMedian)}</span><small>{stats.stats.sampleCount} сохранённых расчётов. Финальную цену определяет калькулятор.</small></div>}<div className="request-role-actions"><button type="button" className="request-danger-link" onClick={onRemove}>Удалить позицию</button></div></div>}</article>;
}

const headerAliases:Record<string,string>={"специальность":"specialty","профессия":"specialty","позиция":"specialty","должность":"specialty","количество":"count","кол-во":"count","численность":"count","график":"pattern","начало смены":"shiftStart","конец смены":"shiftEnd","оплачиваемые часы":"paidHours","оплачиваемых часов":"paidHours","опыт":"experience","разряд":"grade","квалификация":"grade","требования":"skills","описание работ":"description","что делать":"description","допуски":"certificates","удостоверения":"certificates","комментарий":"comment","ставка заказчика":"targetClientRate","ставка":"targetClientRate"};
function normalizeHeader(value:string){return value.trim().toLowerCase().replace(/\s+/g," ");}
function rowsToPreview(rows:string[][],specialties:WorkspaceSpecialty[]):ImportPreview[]{if(rows.length<2)throw new Error("В файле нет строк с позициями");const keys=rows[0].map((header)=>headerAliases[normalizeHeader(header)]??"");if(!keys.includes("specialty")||!keys.includes("count"))throw new Error("Не найдены обязательные колонки «Специальность» и «Количество». Используйте наш шаблон или переименуйте колонки.");return rows.slice(1).map((values,rowIndex)=>{const data:Record<string,string>={};keys.forEach((key,index)=>{if(key)data[key]=(values[index]??"").trim();});const specialtyName=data.specialty??"";const known=specialties.find((item)=>item.name.toLowerCase()===specialtyName.toLowerCase());const count=Number(String(data.count??"").replace(",","."));const errors:string[]=[];if(!specialtyName)errors.push("нет специальности");if(!Number.isFinite(count)||count<=0)errors.push("некорректное количество");const schedule:Record<string,unknown>={};if(data.pattern)schedule.pattern=data.pattern;if(data.shiftStart)schedule.shiftStart=data.shiftStart;if(data.shiftEnd)schedule.shiftEnd=data.shiftEnd;if(data.paidHours)schedule.paidHours=Number(data.paidHours.replace(",","."))||data.paidHours;const requirements:Record<string,unknown>={};if(data.experience){requirements.experienceMode="required";requirements.experienceMin=data.experience;}if(data.grade)requirements.grade=data.grade;if(data.skills)requirements.skills=data.skills;if(data.description)requirements.description=data.description;if(data.certificates)requirements.certificates=data.certificates;if(data.comment)requirements.comment=data.comment;return {row:rowIndex+2,specialtyName,specialtyId:known?.id??"",count:Number.isFinite(count)?Math.round(count):0,schedule,requirements,targetClientRate:data.targetClientRate?Number(data.targetClientRate.replace(",","."))||null:null,errors};}).filter((row)=>row.specialtyName||row.count);}
async function readSpreadsheet(file:File):Promise<string[][]>{const lower=file.name.toLowerCase();if(lower.endsWith(".xlsx"))return readXlsx(await file.arrayBuffer());const content=await file.text();if(lower.endsWith(".xls")||content.includes("urn:schemas-microsoft-com:office:spreadsheet"))return readSpreadsheetXml(content);return parseDelimited(content,lower.endsWith(".tsv")?"\t":detectDelimiter(content));}
function detectDelimiter(textValue:string){const first=textValue.split(/\r?\n/,1)[0]??"";const candidates=[";","\t",","];return candidates.sort((a,b)=>first.split(b).length-first.split(a).length)[0];}
function parseDelimited(source:string,delimiter:string){const rows:string[][]=[];let row:string[]=[];let cell="";let quoted=false;for(let index=0;index<source.length;index++){const char=source[index];if(char==='"'){if(quoted&&source[index+1]==='"'){cell+='"';index++;}else quoted=!quoted;}else if(char===delimiter&&!quoted){row.push(cell);cell="";}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&source[index+1]==='\n')index++;row.push(cell);if(row.some((item)=>item.trim()))rows.push(row);row=[];cell="";}else cell+=char;}row.push(cell);if(row.some((item)=>item.trim()))rows.push(row);return rows;}
function readSpreadsheetXml(xml:string){const doc=new DOMParser().parseFromString(xml,"application/xml");return Array.from(doc.getElementsByTagNameNS("urn:schemas-microsoft-com:office:spreadsheet","Row")).map((row)=>Array.from(row.getElementsByTagNameNS("urn:schemas-microsoft-com:office:spreadsheet","Cell")).map((cell)=>cell.textContent??""));}
async function readXlsx(buffer:ArrayBuffer):Promise<string[][]>{const bytes=new Uint8Array(buffer);const view=new DataView(buffer);let eocd=-1;for(let index=bytes.length-22;index>=Math.max(0,bytes.length-66000);index--){if(view.getUint32(index,true)===0x06054b50){eocd=index;break;}}if(eocd<0)throw new Error("Не удалось прочитать файл таблицы: структура файла повреждена");const entries=view.getUint16(eocd+10,true);let offset=view.getUint32(eocd+16,true);const files=new Map<string,{method:number;size:number;compressed:number;local:number}>();for(let index=0;index<entries;index++){if(view.getUint32(offset,true)!==0x02014b50)break;const method=view.getUint16(offset+10,true);const compressed=view.getUint32(offset+20,true);const size=view.getUint32(offset+24,true);const nameLength=view.getUint16(offset+28,true);const extraLength=view.getUint16(offset+30,true);const commentLength=view.getUint16(offset+32,true);const local=view.getUint32(offset+42,true);const name=new TextDecoder().decode(bytes.slice(offset+46,offset+46+nameLength));files.set(name,{method,size,compressed,local});offset+=46+nameLength+extraLength+commentLength;}
  async function entry(name:string){const info=files.get(name);if(!info)return "";const localName=view.getUint16(info.local+26,true);const localExtra=view.getUint16(info.local+28,true);const start=info.local+30+localName+localExtra;const chunk=bytes.slice(start,start+info.compressed);if(info.method===0)return new TextDecoder().decode(chunk);if(info.method!==8)throw new Error("Файл таблицы использует неподдерживаемый метод сжатия");const stream=new Blob([chunk]).stream().pipeThrough(new DecompressionStream("deflate-raw"));return new TextDecoder().decode(await new Response(stream).arrayBuffer());}
  const sharedXml=await entry("xl/sharedStrings.xml");const shared=sharedXml?Array.from(new DOMParser().parseFromString(sharedXml,"application/xml").getElementsByTagName("si")).map((item)=>item.textContent??""):[];const sheetName=[...files.keys()].find((name)=>/^xl\/worksheets\/sheet\d+\.xml$/.test(name));if(!sheetName)throw new Error("В файле таблицы не найден рабочий лист");const sheet=new DOMParser().parseFromString(await entry(sheetName),"application/xml");const result:string[][]=[];for(const rowNode of Array.from(sheet.getElementsByTagName("row"))){const row:string[]=[];for(const cell of Array.from(rowNode.getElementsByTagName("c"))){const ref=cell.getAttribute("r")??"A1";const letters=(ref.match(/[A-Z]+/i)?.[0]??"A").toUpperCase();let column=0;for(const letter of letters)column=column*26+letter.charCodeAt(0)-64;column--;const type=cell.getAttribute("t");const raw=cell.getElementsByTagName("v")[0]?.textContent??cell.textContent??"";row[column]=type==="s"?shared[Number(raw)]??"":raw;}result.push(row.map((item)=>item??""));}return result;}
function excelTemplate(){const headers=["Специальность","Количество","График","Начало смены","Конец смены","Оплачиваемые часы","Опыт","Разряд / квалификация","Требования","Описание работ","Допуски / удостоверения","Комментарий","Ставка заказчика"];const sample=["Комплектовщик","10","6/1","08:00","20:00","11","Не требуется","","Работа на складе","Сборка заказов","","Пример строки — удалите перед загрузкой",""];const cell=(value:string)=>`<Cell><Data ss:Type="${/^\d+(?:[.,]\d+)?$/.test(value)?"Number":"String"}">${escapeXml(value)}</Data></Cell>`;return `<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Позиции"><Table><Row>${headers.map(cell).join("")}</Row><Row>${sample.map(cell).join("")}</Row></Table></Worksheet></Workbook>`;}
function escapeXml(value:string){return value.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
